  _ = `Đang dùng`,
  _ = `%1$s (%2$s)`,
  _ = `Analog`,
  _ = `Cò`,
  _ = `Nút`,
  _ = `Thêm điều khiển`,
  _ = `Đổi điều khiển`,
  _ = `Đổi lệnh`,
  _ = `Gỡ điều khiển`,
  _ = `Sửa điều khiển`,
  _ = `Thiết lập`,
