  _ = `Dùng haptic cường độ thấp.`,
  _ = `Cường độ haptic - Trung bình`,
  _ = `Dùng haptic cường độ trung bình.`,
  _ = `Cường độ haptic - Cao`,
  _ = `Dùng haptic cường độ cao.`,
  _ = `Lệnh cuộn theo chiều kim đồng hồ`,
  _ = `Bạn có thể gán phím hoặc tương tác để gửi tới trò chơi khi xoay theo chiều kim đồng hồ.`,
  _ = `Lệnh cuộn ngược chiều kim đồng hồ`,
  _ = `Bạn có thể gán phím hoặc tương tác để gửi tới trò chơi khi xoay ngược chiều kim đồng hồ.`,
  _ = `Nhấp`,
  _ = `Lệnh này sẽ được thực thi khi nhấp bàn cảm ứng/cần trỏ.`,
  _ = `Chạm`,
  _ = `Lệnh này sẽ được thực thi khi chạm bàn cảm ứng/cần trỏ.`,
  _ = `Lệnh danh sách cuộn 1`,
  _ = `Bạn có thể gán một nút hoặc phím để gửi tín hiệu tới trò chơi khi cuộn tới nút đầu tiên.`,
  _ = `Lệnh danh sách cuộn 2`,
  _ = `Bạn có thể gán một nút hoặc phím để gửi tín hiệu tới trò chơi khi cuộn tới nút thứ hai.`,
  _ = `Lệnh danh sách cuộn 3`,
  _ = `Bạn có thể gán một nút hoặc phím để gửi tín hiệu tới trò chơi khi cuộn tới nút thứ ba.`,
  _ = `Lệnh danh sách cuộn 4`,
  _ = `Bạn có thể gán một nút hoặc phím để gửi tín hiệu tới trò chơi khi cuộn tới nút thứ tư.`,
  _ = `Lệnh danh sách cuộn 5`,
  _ = `Bạn có thể gán một nút hoặc phím để gửi tín hiệu tới trò chơi khi cuộn tới nút thứ năm.`,
  _ = `Lệnh danh sách cuộn 6`,
  _ = `Bạn có thể gán một nút hoặc phím để gửi tín hiệu tới trò chơi khi cuộn tới nút thứ sáu.`,
  _ = `Lệnh danh sách cuộn 7`,
  _ = `Bạn có thể gán một nút hoặc phím để gửi tín hiệu tới trò chơi khi cuộn tới nút thứ bảy.`,
  _ = `Lệnh danh sách cuộn 8`,
  _ = `Bạn có thể gán một nút hoặc phím để gửi tín hiệu tới trò chơi khi cuộn tới nút thứ tám.`,
  _ = `Lệnh danh sách cuộn 9`,
  _ = `Bạn có thể gán một nút hoặc phím để gửi tín hiệu tới trò chơi khi cuộn tới nút thứ chín.`,
  _ = `Lệnh danh sách cuộn 10`,
  _ = `Bạn có thể gán một nút hoặc phím để gửi tín hiệu tới trò chơi khi cuộn tới nút thứ mười.`,
  _ = `Lặp danh sách`,
  _ = `Nếu chọn, khi vuốt tới một trong hai đầu của danh sách lệnh nút cuộn, sẽ vòng trở về đầu bên kia. Nếu không, vuốt tới điểm cuối sẽ không kích hoạt bất kỳ lệnh nào.`,
  _ = `Lặp danh sách - Bật`,
  _ = `Khi cuộn theo một chiều duy nhất, danh sách phím sẽ làm mới khi tới phím đầu tiên/cuối cùng.`,
  _ = `Lặp danh sách - Tắt`,
  _ = `Khi cuộn qua danh sách mệnh lệnh và tới lệnh đầu tiên/cuối cùng, sẽ không có tín hiệu tương tác nào được gửi đi tiếp cho đến khi đổi chiều ngược lại.`,
  _ = `Hướng vuốt`,
  _ = `Chọn loại tương tác phù hợp để di chuyển qua danh sách lệnh.`,
  _ = `Nút cuộn - Hướng xoáy tròn`,
  _ = `Nút cuộn sẽ được vuốt theo chuyển động xoáy tròn`,
  _ = `Thực hiện chuyển động tròn để đi tới trước hoặc giật lùi trong danh sách lệnh của nút cuộn.`,
  _ = `Nút cuộn - Hướng ngang`,
  _ = `Nút cuộn sẽ được vuốt theo chiều ngang`,
  _ = `Nút cuộn - Hướng dọc`,
  _ = `Nút cuộn sẽ được vuốt theo chiều dọc`,
  _ = `Đảo hướng vuốt`,
  _ = `Đảo hướng bạn cần vuốt để di chuyển 'tới trước' trong danh sách lệnh cho nút cuộn này.`,
  _ = `Nút cuộn thông thường`,
  _ = `Hướng cuộn sẽ không bị đảo ngược.`,
  _ = `Nút cuộn đảo ngược.`,
  _ = `Hướng cuộn sẽ bị đảo ngược.`,
  _ = `Ma sát lăn`,
  _ = `Chỉ số này quyết định nút cuộn sẽ tiếp tục lăn trong bao lâu sau khi được tương tác. Ma sát thấp hơn tương đương với việc lăn lâu hơn.`,
  _ = `Ma sát nút cuộn - Tắt`,
  _ = `Nếu tắt, thì nút cuộn sẽ không có quán tính. Điều này tương đương với việc tắt tính năng của nút cuộn.`,
  _ = `Ma sát nút cuộn - Thấp`,
  _ = `Với ma sát thấp, nút cuộn sẽ xoay trong một khoảng thời gian dài, và dừng lại sau một khoảng thời gian.`,
  _ = `Ma sát nút cuộn - Trung bình`,
  _ = `Với ma sát trung bình, nút cuộn sẽ xoay trong một khoảng thời gian vừa phải, và từ từ dừng sau khi được tương tác.`,
  _ = `Ma sát nút cuộn - Cao`,
  _ = `Với ma sát cao, nút cuộn sẽ chỉ xoay trong một khoảng thời gian ngắn, và nhanh chóng dừng hẳn sau khi được tương tác.`,
  _ = `Ma sát nút cuộn - Không`,
  _ = `Khi không có ma sát, nút cuộn sẽ xoay mãi sau khi được tương tác, và cứ thế xoay cho đến khi có tác động ngoài xen vào.`,
  _ = `Cách tương tác - Menu cảm ứng`,
  _ = `Tương tác này sẽ hoạt động như một menu cảm ứng. Khi tay bạn chạm vào bàn cảm ứng, menu cảm ứng sẽ hiển thị trên màn hình. Nhấp vào một trong các nút hiện thấy sẽ kích hoạt mệnh lệnh tương ứng. Menu cảm ứng có thể có nhiều loại nút, bố cục, kích thước, độ mờ, và dùng biểu tượng đại diện.`,
